  ('wellbeing.swipe.sleep', 'wellbeing', 'swipe', 'Ich schlafe unter der Woche genug.', null, false, false, 0.5, 'student'),
  ('digital.swipe.wifi', 'digital', 'swipe', 'Das WLAN funktioniert, wenn wir es brauchen.', null, false, false, 0.5, 'student'),
  ('participation.swipe.sv', 'participation', 'swipe', 'Unsere SV kann wirklich etwas verändern.', null, false, false, 0.5, 'student'),
  ('building.swipe.toilet', 'building', 'swipe', 'Ich gehe in der Schule ohne Bedenken auf die Toilette.', null, false, false, 0.5, 'student'),
